module prim_arbiter_fixed #(
  parameter int N   = 8,
  parameter int DW  = 32,

  // Configurations
  // EnDataPort: {0, 1}, if 0, input data will be ignored
  parameter bit EnDataPort = 1,

  // Derived parameters
  localparam int IdxW = $clog2(N)
) (
  // used for assertions only
  input clk_i,
  input rst_ni,

  input        [ N-1:0]    req_i,
  input        [DW-1:0]    data_i [N],
  output logic [ N-1:0]    gnt_o,
  output logic [IdxW-1:0]  idx_o,

  output logic             valid_o,
  output logic [DW-1:0]    data_o,
  input                    ready_i
);

  `ASSERT_INIT(CheckNGreaterZero_A, N > 0)

  // this case is basically just a bypass
  if (N == 1) begin : gen_degenerate_case

// AUTO-SLICE KEEP assign lines 31-31 signals=req_i,valid_o
    assign valid_o  = req_i[0];
// AUTO-SLICE OMIT assign lines 32-32
// AUTO-SLICE KEEP assign lines 33-33 signals=gnt_o,ready_i,valid_o
    assign gnt_o[0] = valid_o & ready_i;
// AUTO-SLICE KEEP assign lines 34-34 signals=idx_o
    assign idx_o    = '0;

  end else begin : gen_normal_case

    // align to powers of 2 for simplicity
    // a full binary tree with N levels has 2**N + 2**N-1 nodes
    wire [2**(IdxW+1)-2:0]           req_tree;
    wire [2**(IdxW+1)-2:0]           gnt_tree;
    wire [2**(IdxW+1)-2:0][IdxW-1:0] idx_tree;
    wire [2**(IdxW+1)-2:0][DW-1:0]   data_tree;

    for (genvar level = 0; level < IdxW+1; level++) begin : gen_tree
      //
      // level+1   C0   C1   <- "Base1" points to the first node on "level+1",
      //            \  /         these nodes are the children of the nodes one level below
      // level       Pa      <- "Base0", points to the first node on "level",
      //                         these nodes are the parents of the nodes one level above
      //
      // hence we have the following indices for the Pa, C0, C1 nodes:
      // Pa = 2**level     - 1 + offset       = Base0 + offset
      // C0 = 2**(level+1) - 1 + 2*offset     = Base1 + 2*offset
      // C1 = 2**(level+1) - 1 + 2*offset + 1 = Base1 + 2*offset + 1
      //
      localparam int Base0 = (2**level)-1;
      localparam int Base1 = (2**(level+1))-1;

      for (genvar offset = 0; offset < 2**level; offset++) begin : gen_level
        localparam int Pa = Base0 + offset;
        localparam int C0 = Base1 + 2*offset;
        localparam int C1 = Base1 + 2*offset + 1;

        // this assigns the gated interrupt source signals, their
        // corresponding IDs and priorities to the tree leafs
        if (level == IdxW) begin : gen_leafs
          if (offset < N) begin : gen_assign
            // forward path
// AUTO-SLICE KEEP assign lines 70-70 signals=req_i
            assign req_tree[Pa]      = req_i[offset];
// AUTO-SLICE OMIT assign lines 71-71
// AUTO-SLICE OMIT assign lines 72-72
            // backward (grant) path
// AUTO-SLICE KEEP assign lines 74-74 signals=gnt_o
            assign gnt_o[offset]     = gnt_tree[Pa];

          end else begin : gen_tie_off
            // forward path
// AUTO-SLICE OMIT assign lines 78-78
// AUTO-SLICE OMIT assign lines 79-79
// AUTO-SLICE OMIT assign lines 80-80
            logic unused_sigs;
